// Research pilot server. Requires a persistent DATA_DIR for remote deployment.
const http=require('http'),fs=require('fs'),path=require('path'),crypto=require('crypto'),zlib=require('zlib');
const nodemailer=process.env.SMTP_HOST?require('nodemailer'):null;
const PORT=Number(process.env.PORT||3000),DATA_DIR=path.resolve(process.env.DATA_DIR||'./pilot-data');
const activeGenerations=new Set(); const jobs=new Map();
const mailer=process.env.SMTP_HOST&&process.env.SMTP_USER&&process.env.SMTP_PASS?nodemailer.createTransport({host:process.env.SMTP_HOST,port:Number(process.env.SMTP_PORT||587),secure:process.env.SMTP_PORT==='465',auth:{user:process.env.SMTP_USER,pass:process.env.SMTP_PASS}}):null;
const emailReady=()=>Boolean(mailer&&process.env.RESEARCHER_EMAIL&&process.env.SMTP_FROM);
const validSession=(id,token)=>fs.existsSync(file(id,'.auth'))&&typeof token==='string'&&sha(token)===JSON.parse(fs.readFileSync(file(id,'.auth'),'utf8')).tokenHash;
async function sendCompletionEmail(id){if(!emailReady())throw Error('Email service not configured');const data=fs.readFileSync(file(id,'.json'));const session=JSON.parse(data);const attachment=zlib.gzipSync(data,{level:9});if(attachment.length>18*1024*1024)throw Error('Compressed session exceeds safe email attachment limit; retrieve from researcher dashboard instead');await mailer.sendMail({from:process.env.SMTP_FROM,to:process.env.RESEARCHER_EMAIL,subject:`Co-Ideation ${session.participant} — completed session`,text:`Participant: ${session.participant}\nSession: ${id}\nThe attached .json.gz contains all recorded sketches, generated images, questionnaire answers and event logs. Extract the .gz before importing it into researcher.html.`,attachments:[{filename:`${session.participant}_${id}.json.gz`,content:attachment,contentType:'application/gzip'}]});}

fs.mkdirSync(DATA_DIR,{recursive:true});
const sha=x=>crypto.createHash('sha256').update(x).digest('hex');
const okId=id=>/^[a-f0-9-]{36}$/.test(id||'');
const file=(id,ext)=>path.join(DATA_DIR,id+ext);
const reply=(res,status,obj)=>{res.writeHead(status,{'Content-Type':'application/json','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'});res.end(JSON.stringify(obj))};
const read=async(req)=>{const chunks=[];let size=0;for await(const part of req){size+=part.length;if(size>150*1024*1024)throw Error('Payload too large');chunks.push(part)}return JSON.parse(Buffer.concat(chunks).toString('utf8'))};
const saveJSON=(p,obj)=>{const temp=p+'.'+crypto.randomBytes(6).toString('hex')+'.tmp';fs.writeFileSync(temp,JSON.stringify(obj),{mode:0o600});fs.renameSync(temp,p)};
const allocations={"P1": {"assignment": "T1-C2", "sequence": ["S1-A", "S2-D", "U1-C", "U2-B"]}, "P2": {"assignment": "T1-C4", "sequence": ["S1-D", "S2-A", "U1-C", "U2-B"]}, "P3": {"assignment": "T2-C8", "sequence": ["S1-C", "S2-B", "U2-D", "U1-A"]}, "P4": {"assignment": "T3-C7", "sequence": ["S2-C", "S1-B", "U1-A", "U2-D"]}, "P5": {"assignment": "T4-C1", "sequence": ["S2-A", "S1-D", "U2-B", "U1-C"]}, "P6": {"assignment": "T4-C5", "sequence": ["S2-B", "S1-C", "U2-A", "U1-D"]}, "P7": {"assignment": "T5-C5", "sequence": ["U1-B", "U2-C", "S1-A", "S2-D"]}, "P8": {"assignment": "T5-C6", "sequence": ["U1-B", "U2-C", "S1-D", "S2-A"]}, "P9": {"assignment": "T6-C4", "sequence": ["U1-D", "U2-A", "S2-C", "S1-B"]}, "P10": {"assignment": "T7-C3", "sequence": ["U2-D", "U1-A", "S1-B", "S2-C"]}, "P11": {"assignment": "T8-C1", "sequence": ["U2-A", "U1-D", "S2-B", "S1-C"]}, "P12": {"assignment": "T8-C8", "sequence": ["U2-C", "U1-B", "S2-D", "S1-A"]}};
const config={A:["low","low"],B:["high","high"],C:["low","high"],D:["high","low"]};
function zipStore(entries){let offset=0;const chunks=[],central=[];for(const [name,value] of Object.entries(entries)){const n=Buffer.from(name),d=Buffer.from(value);let crc=0xffffffff;for(const x of d){crc^=x;for(let j=0;j<8;j++)crc=(crc>>>1)^((crc&1)?0xedb88320:0)}crc=(crc^0xffffffff)>>>0;const h=Buffer.alloc(30);h.writeUInt32LE(0x04034b50);h.writeUInt16LE(20,4);h.writeUInt32LE(crc,14);h.writeUInt32LE(d.length,18);h.writeUInt32LE(d.length,22);h.writeUInt16LE(n.length,26);const c=Buffer.alloc(46);c.writeUInt32LE(0x02014b50);c.writeUInt16LE(20,4);c.writeUInt16LE(20,6);c.writeUInt32LE(crc,16);c.writeUInt32LE(d.length,20);c.writeUInt32LE(d.length,24);c.writeUInt16LE(n.length,28);c.writeUInt32LE(offset,42);chunks.push(h,n,d);central.push(c,n);offset+=h.length+n.length+d.length}const cd=Buffer.concat(central),end=Buffer.alloc(22);end.writeUInt32LE(0x06054b50);end.writeUInt16LE(Object.keys(entries).length,8);end.writeUInt16LE(Object.keys(entries).length,10);end.writeUInt32LE(cd.length,12);end.writeUInt32LE(offset,16);return Buffer.concat([...chunks,cd,end])}
function sessionZip(data){const entries={'session.json':JSON.stringify(data,null,2),'events.json':JSON.stringify(data.events,null,2),'questionnaires.json':JSON.stringify({pretest:data.pretest,conditions:data.conditions.map(c=>({task:c.task,id:c.id,answers:c.answers,comparison:c.comparison}))},null,2)};for(const c of data.conditions)for(const [i,it] of c.iterations.entries())for(const [j,src] of [it.input,...it.outputs].entries())if(typeof src==='string'&&src.startsWith('data:image/png;base64,'))entries[`images/${c.task}-${c.id}/iteration-${i+1}-${j?'AI-'+j:'sketch'}.png`]=Buffer.from(src.split(',')[1],'base64');return zipStore(entries)}
const pages={};
pages["participant.html"]=Buffer.from("","base64");
pages["researcher.html"]=Buffer.from("","base64");
const serve=(res,name)=>{res.writeHead(200,{"Content-Type":"text/html; charset=utf-8","Cache-Control":"no-store"});res.end(pages[name]);};
http.createServer(async(req,res)=>{try{const u=new URL(req.url,'http://localhost'),a=u.pathname.split('/').filter(Boolean);
if(['GET','HEAD'].includes(req.method)&&['/','/participant.html','/researcher.html','/index.html'].includes(u.pathname))return serve(res,u.pathname==='/researcher.html'?'researcher.html':'participant.html');
if(req.method==='POST'&&u.pathname==='/api/session-start'){const body=await read(req);if(!Object.hasOwn(allocations,body.participant))return reply(res,400,{error:'Unknown participant ID'});const id=crypto.randomUUID(),token=crypto.randomBytes(32).toString('hex');saveJSON(file(id,'.auth'),{participant:body.participant,tokenHash:sha(token),createdAt:new Date().toISOString()});return reply(res,200,{id,token})}
if(req.method==='GET'&&a[0]==='api'&&a[1]==='job'&&okId(a[2])){const id=req.headers['x-session-id'];if(!okId(id)||!validSession(id,req.headers['x-session-token']))return reply(res,403,{error:'Session authorization failed'});const owner=JSON.parse(fs.readFileSync(file(id,'.auth'))).participant;const jp=file(a[2],'.job');if(!fs.existsSync(jp))return reply(res,409,{error:'Generation interrupted by restart; retry manually'});const j=JSON.parse(fs.readFileSync(jp));if(j.owner!==owner)return reply(res,403,{error:'Session authorization failed'});if(j.status==='pending'&&!jobs.has(a[2]))return reply(res,409,{error:'Generation interrupted by restart; retry manually'});return reply(res,j.status==='pending'?202:j.status==='done'?200:502,j.result||{pending:true})}
if(req.method==='POST'&&u.pathname==='/api/generate'){
 const id=req.headers['x-session-id'],token=req.headers['x-session-token'];if(!okId(id)||!validSession(id,token))return reply(res,403,{error:'Session authorization failed'});
 if(!process.env.OPENAI_API_KEY)return reply(res,503,{error:'OPENAI_API_KEY is not configured on the server'});
 if(activeGenerations.has(id))return reply(res,429,{error:'Generation already in progress'});
 const body=await read(req);if(body.quantity!==3||!['low','high'].includes(body.fidelity)||typeof body.sketch!=='string'||!/^data:image\/png;base64,/.test(body.sketch)||body.sketch.length>9e6||!['low','high'].includes(body.diversity)||!["S1","S2","U1","U2"].includes(body.task)||typeof body.prompt!=='string'||body.prompt.length>1500)return reply(res,400,{error:'Invalid generation request'});
 const authFile=file(id,'.auth'),state=JSON.parse(fs.readFileSync(authFile,'utf8'));const expected=allocations[state.participant]?.sequence[body.position];if(expected!==body.task+'-'+body.condition||config[body.condition]?.[0]!==body.fidelity||config[body.condition]?.[1]!==body.diversity)return reply(res,400,{error:'Condition does not match assigned sequence'});if((state.generations||0)>=40)return reply(res,429,{error:'Pilot generation limit reached'});
 const job=u.searchParams.get('job');if(job&&!okId(job))return reply(res,400,{error:'Invalid job'});if(job&&fs.existsSync(file(job,'.job')))return reply(res,202,{pending:true});if(job){saveJSON(file(job,'.job'),{owner:state.participant,status:'pending'});jobs.set(job,true);reply(res,202,{pending:true})}const finish=(status,result)=>{if(job){saveJSON(file(job,'.job'),{owner:state.participant,status:status===200?'done':'failed',result});jobs.delete(job);return;}return reply(res,status,result)};activeGenerations.add(id);try{const sketch=Buffer.from(body.sketch.split(',')[1],'base64');const fidelity=body.fidelity;const base=fidelity==='low'?'Draw a genuine early freehand sketch, matching the input stroke character, looseness, ambiguity and level of detail. Use sparse exploratory marks, incomplete contours and white space where appropriate. Do not create a finished render with a sketch filter, photorealism, polished UI, or invented detail.':'Produce a clean, polished visualization of the participant’s intended idea. Refine geometry and linework; use appropriate materials, lighting or UI typography and hierarchy only where relevant. Do not add unrelated content.';
 const instructions=`Transform the supplied drawing according to the participant's request. The drawing and request are the only subject matter. Do not invent a setting, background, scene or unrelated objects. Preserve unspecified elements. If no request is given, interpret the visible marks conservatively. ${base} Participant request: ${body.prompt.trim()||'(No text request.)'}`;
 const variation=body.diversity==='low'?['Create a faithful interpretation.','Keep the same core idea but make a noticeable small variation in shape or detail.','Keep the same core idea but make a different noticeable small variation in shape or detail.']:['Offer one interpretation of the requested subject.','Offer a genuinely different interpretation of the requested subject, varying its form or organization.','Offer another distinct alternative to the requested subject, without adding unrelated context.'];
 const generateOne=async(i,anchor)=>{const form=new FormData();form.append('model',process.env.OPENAI_IMAGE_MODEL||'gpt-image-1.5');form.append('size','1536x1024');form.append('quality',process.env.OPENAI_IMAGE_QUALITY||'medium');form.append('output_format','png');form.append('image[]',new Blob([sketch],{type:'image/png'}),'sketch.png');if(anchor)form.append('image[]',new Blob([Buffer.from(anchor.split(',')[1],'base64')],{type:'image/png'}),'anchor.png');else if(typeof body.reference==='string'&&/^data:image\/png;base64,/.test(body.reference)&&body.reference.length<9e6)form.append('image[]',new Blob([Buffer.from(body.reference.split(',')[1],'base64')],{type:'image/png'}),'reference.png');form.append('prompt',instructions+' '+variation[i]+(anchor?' The second image is the first generated suggestion: use it as the concept and composition anchor, preserving the participant request.':''));const response=await fetch('https://api.openai.com/v1/images/edits',{method:'POST',headers:{Authorization:'Bearer '+process.env.OPENAI_API_KEY},body:form,signal:AbortSignal.timeout(240000)});const result=await response.json();if(!response.ok||!result.data?.[0]?.b64_json)throw Error(result.error?.message||'Image API returned no image');return 'data:image/png;base64,'+result.data[0].b64_json};
 const first=await generateOne(0);const outputs=[first,...await Promise.all([1,2].map(i=>generateOne(i,body.diversity==='low'?first:null)))];state.generations=(state.generations||0)+1;saveJSON(authFile,state);return finish(200,{outputs,promptVersion:'fidelity-diversity-v2',model:process.env.OPENAI_IMAGE_MODEL||'gpt-image-1.5'});
 }catch(e){console.error('Generation error:',e.message);return finish(502,{error:'Image generation failed: '+e.message})}finally{activeGenerations.delete(id)}
}
if(req.method==='GET'&&a[0]==='api'&&a[1]==='export'&&okId(a[2])){const id=a[2];if(!validSession(id,req.headers['x-session-token']))return reply(res,403,{error:'Session authorization failed'});if(!fs.existsSync(file(id,'.json')))return reply(res,409,{error:'Session not saved'});const data=JSON.parse(fs.readFileSync(file(id,'.json'),'utf8'));const zip=sessionZip(data);res.writeHead(200,{'Content-Type':'application/zip','Cache-Control':'no-store','Content-Disposition':'attachment; filename="session.zip"'});return res.end(zip)}
if(req.method==='POST'&&a[0]==='api'&&a[1]==='complete'&&okId(a[2])){const id=a[2];if(!validSession(id,req.headers['x-session-token']))return reply(res,403,{error:'Session authorization failed'});if(!fs.existsSync(file(id,'.json')))return reply(res,409,{error:'Session not yet uploaded'});const data=JSON.parse(fs.readFileSync(file(id,'.json'),'utf8'));if(data.stage!=='complete')return reply(res,409,{error:'Study not yet completed'});if(fs.existsSync(file(id,'.emailed')))return reply(res,200,{emailed:true,alreadySent:true});try{await sendCompletionEmail(id);saveJSON(file(id,'.emailed'),{sentAt:new Date().toISOString()});return reply(res,200,{emailed:true})}catch(e){console.error('Email delivery failed:',e.message);return reply(res,503,{emailed:false,error:e.message})}}
if(req.method==='PUT'&&a[0]==='api'&&a[1]==='session'&&okId(a[2])){
 const id=a[2],token=req.headers['x-session-token'];if(!validSession(id,token))return reply(res,403,{error:'Session authorization failed'});
 const body=await read(req);if(!body||!Array.isArray(body.conditions)||body.conditions.length!==4||!Array.isArray(body.events)||typeof body.participant!=='string')return reply(res,400,{error:'Invalid session format'});
 // Avoid accidental overwrite of one participant's data by another session.
 if(fs.existsSync(file(id,'.json'))){const old=JSON.parse(fs.readFileSync(file(id,'.json')));if(old.id!==body.id||old.participant!==body.participant)return reply(res,409,{error:'Session mismatch'})}
 saveJSON(file(id,'.json'),body);return reply(res,200,{saved:true,updatedAt:new Date().toISOString()})}
// Researcher data is imported locally from the participant email attachment.
return reply(res,404,{error:'Not found'});
}catch(e){console.error(e);return reply(res,e.message==='Payload too large'?413:500,{error:e.message==='Payload too large'?'Payload too large':'Server error'})}
}).listen(PORT,'0.0.0.0',()=>{console.log('Co-Ideation pilot listening on '+PORT);const base=process.env.RENDER_EXTERNAL_URL;if(base){console.log('PARTICIPANT URL: '+base+'/');console.log('RESEARCHER URL: '+base+'/researcher.html');}});
